private static long calculateChunkSize(long fileSize) {
        int divisor = cpus;
        long chunkSize;
        if (fileSize > 10_000) {
            while ((chunkSize = fileSize / divisor) > Integer.MAX_VALUE - 512) {
                divisor *= 2;
            }
            return chunkSize;
        }
        return fileSize;
    }

